CREATE TABLE book(id TEXT PRIMARY KEY,sequence INTEGER UNIQUE NOT NULL,title TEXT NOT NULL,source_record TEXT NOT NULL,source_sha256 TEXT NOT NULL,source_commit TEXT NOT NULL,inventory_json TEXT NOT NULL,queue_order INTEGER UNIQUE,status TEXT NOT NULL,next_action TEXT,edition_json TEXT,review TEXT,revision INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE unit(book_id TEXT REFERENCES book,seq INTEGER NOT NULL,id TEXT NOT NULL,source_locator TEXT NOT NULL,source_anchor TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','draft','self_reviewed')),body TEXT,body_sha256 TEXT,reviewed_at TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(book_id,id),UNIQUE(book_id,seq));
CREATE VIEW queue AS SELECT * FROM book WHERE queue_order IS NOT NULL AND status NOT IN ('translated_self_reviewed','deferred_incomplete','blocked_source') ORDER BY queue_order;
